const response = pm.response.json();

if (pm.response.code === 200 && response.access_token) {
    pm.environment.set("access_token_admin", response.access_token);
    pm.environment.set("refresh_token_admin", response.refresh_token);
    console.log("✅ Tokeny administratora zapisane pomyślnie.");
} else {
    console.error("❌ Błąd logowania administratora:", response);
}

